INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(115523, 'ruRU', '', 'Ты знаешь, что требуется. Удачи.', 24330),
(115524, 'ruRU', '', 'Даже не увидел твоего приближения.', 24330),
(115525, 'ruRU', '', 'У него не было ни шанса.', 24330),
(115526, 'ruRU', '', 'Правосудие свершилось.', 24330),
(115527, 'ruRU', '', 'Отлично нанесён удар, как у истинного Стража.', 24330),
(115528, 'ruRU', '', 'Легенда о Стражах растёт благодаря твоим деяниям.', 24330),
(115529, 'ruRU', '', 'Мы никогда не сомневались, что ты справишься.', 24330),
(115530, 'ruRU', '', 'Эффективное убийство. Весьма похвально!', 24330),
(115537, 'ruRU', '', 'Нам нужно продолжать двигаться!', 24330),
(115539, 'ruRU', '', 'Кто это так яростно сражается впереди?', 24330),
(115616, 'ruRU', '', 'Я могу перенаправить яд внутри твоих клинков, чтобы открыть новую силу внутри них.\n\nДля тебя это, конечно, бесплатно, но имей в виду, что в процессе будет потеряна часть силы.', 24330),
(115618, 'ruRU', '', 'Я могу использовать магию этой рощи, чтобы помочь тебе изменить силу внутри твоего оружия!\n\nОднако заклинание немного неустойчиво, так что ты потеряешь небольшую часть, когда я его сотворю.', 24330),
(115620, 'ruRU', '', 'Я считаю, что мы можем использовать этих иссохших как оружие. Но сначала нужно научить их выживать в бою.', 24330),
(115624, 'ruRU', '', 'Уничтожьте наших врагов!', 24330),
(115625, 'ruRU', '', 'Сокрушите этих захватчиков!', 24330),
(115626, 'ruRU', '', 'За Одина!', 24330),
(115627, 'ruRU', '', 'Почувствуй мой гнев!', 24330),
(115645, 'ruRU', '', 'Саа''ра всё больше учит меня, как использовать алтарь. Коли хочешь, я смогу помочь те изменить, как сила устроилась в твоём клинке.\n\nПравда, я ещё учусь, так что перенос будет не идеальным. Малая доля силы растворится в Пустоте.', 24330),
(115653, 'ruRU', '', 'Пссст! Эй, $n, сюда!', 24330),
(115655, 'ruRU', '', 'Защитник! Я несу приказы от Седогрива!', 24330),
(115660, 'ruRU', '', 'Вижу по твоим глазам — ты хочешь чего-то другого для того артефакта, что ты держишь. Чего-то нового.\n\nТы пришёл в правильное место, Военачальник. Я могу помочь те... но не обещаю, шо каждая капля окажется там же, где ты её оставил.\n\nДемонья кровь слишком неустойчива для обещаний.', 24330),
(115662, 'ruRU', '', 'Я ОБНОВЛЁН! Идите, малыши. Положим конец этому вторжению!', 24330),
(115665, 'ruRU', '', 'Что я могу для тебя сделать?', 24330),
(115667, 'ruRU', '', 'Идём, Кора, пора домой.', 24330),
(115687, 'ruRU', '', 'Ты имеешь в виду того хмурого, одетого в чёрное дурачка через дорогу? Того, что всё время на меня косится?$b$bДа, я заметила его. Он не первый смертный, одержимый тёмным рейнджером. Не понимаю этой одержимости смертью у некоторых. Ему следовало бы проводить время в погоне за живыми, а не грезить о мимолётной связи с той, что уже умерла.$b$bЖизнь часто пропадает впустую у живых.', 24330),
(115689, 'ruRU', '', 'Я была девой, чистой и верной. Юной охотницей на службе Луносвета, обручённой с благородным господином своей мечты.$b$bПотом пришёл Артас.$b$bЯ погибла в бою, когда безумный принц прорезал чёрный шрам через землю, которую я любила. Но, по крайней мере, я обрела покой, полагаю. На время. Пока Королева Банши не вернула меня из-за грани и не прокляла мою душу на службу себе.$b$bТебе придётся простить меня, если у меня мало терпения на таких глупцов, как Моргот, кто считает само собой разумеющимся то, что имеет, и мыслит найти счастье в боли.', 24330),
(115691, 'ruRU', '', '<Тёмный рейнджер вздыхает.>$b$bПолагаю, в нём есть некое очарование. Он не виноват в своём невежестве.$b$bНо ему нужно понять, что моё сердце не способно чувствовать любовь или счастье, и мы не можем... вступить в ту близость, которой он желает. Я мёртвое, гниющее создание, и меня ждёт лишь бездна.$b$bПрошу, если у тебя есть хоть какая-то привязанность к нему, разбей его сердце сейчас же. Это спасёт его от настоящей боли позже.$b$b<Велонара на мгновение замолкает, затем берёт одну чёрную розу и нежно касается её лепестков.>', 24330),
(115700, 'ruRU', '', 'Не стоит усилий, дорогой! Пусть гниют в своей гробнице. Огни Легиона скоро придут за ними сами.', 24330),
(115711, 'ruRU', '', 'Угх... ох, моя голова!', 24330),
(115717, 'ruRU', '', 'Ох, Камнешаг... твоя жертва не будет напрасной!', 24330),
(115719, 'ruRU', '', 'Я собиратель трав, цветов и растений. Мои путешествия провели меня по всем Расколотым островам, а также в Изумрудный Сон. Как я могу помочь тебе?', 24330),
(115722, 'ruRU', '', 'Конечно, мои дорогие.', 24330),
(115729, 'ruRU', '', 'Я тоже иду!', 24330),
(115730, 'ruRU', '', 'Сегодня мы празднуем великий триумф, оплаченный кровью тех, кто был нам всего дороже.', 24330),
(115731, 'ruRU', '', 'Благодаря твоей отваге древние земли Вал''шары наконец-то могут начать исцеляться.', 24330),
(115732, 'ruRU', '', 'Теперь Слёзы Элуны пополнили наш арсенал. Пусть они принесут нам победу над Легионом!', 24330),
(115734, 'ruRU', '', 'Сегодня мы празднуем великий триумф, оплаченный кровью тех, кто был нам всего дороже.', 24330),
(115735, 'ruRU', '', 'Хотя я часто враждую с твоей Ордой, я не могу усомниться в отваге, что ты проявил, спасая Вал''шару.', 24330),
(115736, 'ruRU', '', 'Теперь Слёзы Элуны пополнили наш арсенал. Пусть они принесут нам победу над Легионом!', 24330),
(115739, 'ruRU', '', 'Малфурион! Где моя любимая?', 24330);
